package com.nook.controller; import com.nook.dto.ApiDtos.*; import com.nook.security.CurrentUser; import com.nook.service.ConversationService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/conversations") public class ConversationController {final ConversationService s;public ConversationController(ConversationService s){this.s=s;}@GetMapping List<ConversationDto> list(){return s.list(CurrentUser.id());}@GetMapping("/{id}/messages") PageDto<MessageDto> messages(@PathVariable UUID id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="50")int size){return s.messages(CurrentUser.id(),id,RequestParameters.page(page),RequestParameters.size(size,100));}@PostMapping("/{id}/messages") @ResponseStatus(HttpStatus.CREATED) MessageDto send(@PathVariable UUID id,@Valid @RequestBody SendMessage x){return s.send(CurrentUser.id(),id,x.body(),x.clientMessageId());}}
